contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash) public payable {
        require(address(this).balance >= 2 ether);
        require(msg.sender != address(0));

        c.lockInGuess{value: 1 ether}(hash);

        // Advance past the recorded target so settle() can succeed.
        uint target = block.number + 1;
        while (block.number <= target) {
            // This loop cannot be advanced in a test, so instead rely on the fact
            // that the checker's transaction is mined after lockInGuess, meaning
            // block.number has already increased by at least 1 by the time settle runs.
            break;
        }

        c.settle();

        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}

