contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash) public payable {
        require(address(this).balance >= 1 ether);

        uint balBefore = address(c).balance;

        c.lockInGuess{value: 1 ether}(hash);

        (, bytes32 storedGuess) = _readGuess(address(this));
        (uint storedBlock, ) = _readGuess(address(this));

        uint balAfterLock = address(c).balance;

        c.settle();

        (uint blockAfterSettle, bytes32 guessAfterSettle) = _readGuess(address(this));

        assert(
            balAfterLock >= balBefore + 1 ether &&
            storedBlock != 0 &&
            storedGuess == hash &&
            blockAfterSettle == 0 &&
            guessAfterSettle == hash
        );
    }

    function _readGuess(address addr) internal view returns (uint, bytes32) {
        return c.guesses(addr);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash) public payable {
        require(address(this).balance >= 1 ether);
        require(block.number < type(uint256).max - 1);

        uint balBefore = address(c).balance;

        c.lockInGuess{value: 1 ether}(hash);

        uint balAfterLock = address(c).balance;
        uint lockBlock = block.number;

        while (block.number <= lockBlock + 1) {
            block.number += 1;
        }

        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        assert(
            balAfterLock == balBefore + 1 ether &&
            !settleReverted &&
            address(c).balance == balBefore
        );
    }

    receive() external payable {}
}

